"""One-time import of the user-approved cinematic site; restores the normal builder."""
from pathlib import Path
import base64, hashlib, io, os, runpy, subprocess, zipfile

if os.environ.get("GITHUB_ACTIONS") != "true":
    raise SystemExit("This one-time import runs in the existing GitHub Pages workflow.")
root = Path(__file__).resolve().parents[1]
expected_parent = "fc6056f52f2e0f65ef1c43f1b1d73516c57dc551"
header = subprocess.check_output(["git", "cat-file", "-p", "HEAD"], cwd=root, text=True).split("\n\n", 1)[0]
parents = [line[7:] for line in header.splitlines() if line.startswith("parent ")]
if parents != [expected_parent]:
    raise SystemExit("Source advanced before publication; reconcile changes before import.")
payload = ''
expected = {'content/gallery.json': 'cb23cda6a8818f43ef543a76f5556076057643fb44042c61cdf0ca562a9aaf88', 'egitim/index.html': '9aa54d02f2a6878719c50d7d814027b3f72e389cd3eb754fd45f3cf84581cfaa', 'galeri/index.html': 'a07ff93b35e867469171c262f04667b93797c4eaa14c42c2cc6761c361987def', 'gallery-home.css': 'e485fe283aa1edce34cf8acc0b19e554466b1a798c29bdb3c1b4fd5e76da01cf', 'gallery.css': '6555aa28c5ae533c1c68a7b0b198c01f1c06a3080e925094df687112a139bdfb', 'gallery.js': '6a7786c86df78beece419229624094afd7b9a7cc4a3ab458f586bbf00d23a1d6', 'index.html': '3ccbcea28725880b2d47a709e3336d51759b78a2a121000a5cb9a85fd1ffcaac', 'scripts/build_content.py': 'a66ecd235eb583d384a7844c4f47bc3f25dbe23d0d0e07cfe8cd59c70b6609ba', 'cinematic.css': 'b8b95e7708444748e4deac63b2c942270bf89bb1f94b2a0d3e2962a17c178424', 'cinematic.js': 'f24da933ca2372a83758f02236882b50053dc833562faade8f0adbcf4824ede1'}
with zipfile.ZipFile(io.BytesIO(base64.b64decode(payload, validate=True))) as archive:
    if set(archive.namelist()) != set(expected):
        raise SystemExit("Unexpected archive contents")
    files = {name: archive.read(name) for name in expected}
    for name, content in files.items():
        if hashlib.sha256(content).hexdigest() != expected[name]:
            raise SystemExit("Import checksum mismatch")
        if Path(name).is_absolute() or ".." in Path(name).parts:
            raise SystemExit("Invalid import path")
    for name, content in files.items():
        target = root / name
        target.parent.mkdir(parents=True, exist_ok=True)
        target.write_bytes(content)
subprocess.run(["git", "add", "--", *expected], cwd=root, check=True)
subprocess.run(["git", "-c", "user.name=github-actions[bot]", "-c", "user.email=41898282+github-actions[bot]@users.noreply.github.com", "commit", "-m", "Publish reviewed cinematic education and gallery"], cwd=root, check=True)
subprocess.run(["git", "push", "origin", "HEAD:main"], cwd=root, check=True)
runpy.run_path(str(root / "scripts/build_content.py"), run_name="__main__")
